import {launchPi} from '<WORKTREE>/tests/system/fixtures/pi-terminal.ts';
import {Schema} from '<WORKTREE>/node_modules/effect/dist/index.js';
import {writeFile, readFile, readdir, stat} from 'node:fs/promises';
import {join} from 'node:path';

const Resource = Schema.Struct({
  label: Schema.String,
  pid: Schema.Number,
  bun: Schema.String,
  cpu: Schema.Struct({user: Schema.Number, system: Schema.Number}),
  memory: Schema.Struct({rss: Schema.Number, heapUsed: Schema.Number, external: Schema.Number}),
});
const samples = Number(process.argv[2] ?? 6);
const turns = Number(process.argv[3] ?? 40);
const readCount = 8;
const source = Array.from({length: 300}, (_, i) => `export const sample${String(i).padStart(3, '0')} = 'retained source ${i}';`).join('\n') + '\n';
const probe = Array.from({length: 100}, (_, i) => `export const probe${String(i).padStart(3, '0')} = ${i}; // WIDTH_${i} ${'界'.repeat(40)} END_${i}`).join('\n') + '\n';
const output = process.argv[4] ?? '/tmp/ui-live-performance.jsonl';
await writeFile(output, '');

for (let sample = 0; sample < samples; sample++) {
  const enabled = process.argv[5] === 'on' || [false, true, true, false, false, true][sample % 6];
  console.log(JSON.stringify({phase: 'start', sample, enabled}));
  const started = performance.now();
  const host = await launchPi(JSON.stringify({ui: {enabled}, rtk: {rewrite: false, ansi: false}}), '/tmp/ui-resource-observer.ts', 'ui');
  const startupMs = performance.now() - started;
  try {
    await writeFile(join(host.agent, 'settings.json'), JSON.stringify({compaction: {enabled: false}}));
    await host.reload();
    await host.terminal.resize({cols: 100, rows: 36});
    await writeFile(join(host.directory, 'source.ts'), source);
    async function resources(label: string) {
      await host.command(`/measure-resources ${label}`);
      let value: typeof Resource.Type | undefined;
      await host.terminal.screen.waitUntil(async () => {
        try {
          value = Schema.decodeUnknownSync(Resource)(JSON.parse(await readFile(join(host.directory, 'resources.json'), 'utf8')));
          return value.label === label;
        } catch { return false; }
      }, {timeoutMs: 5000});
      if (!value) throw new Error('Resource observation missing');
      return value;
    }
    const initial = await resources('initial');
    const longStarted = performance.now();
    for (let turn = 0; turn < turns; turn++) {
      await host.sequence(Array.from({length: readCount}, () => ({name: 'read', parameters: '{"path":"source.ts"}'})));
    }
    await host.invoke('write', JSON.stringify({path: 'probe.ts', content: probe}));
    const loadMs = performance.now() - longStarted;
    const loaded = await resources('loaded');
    const typingMs: number[] = [];
    for (let i = 0; i < 10; i++) {
      const text = `INPUT_SAMPLE_${i}`;
      const now = performance.now();
      await host.terminal.keyboard.type(text);
      await host.terminal.screen.waitForText(text, {timeoutMs: 10000});
      typingMs.push(performance.now() - now);
      await host.terminal.keyboard.press('Control+U');
    }
    const disclosureMs: number[] = [];
    for (let i = 0; i < 10; i++) {
      const now = performance.now();
      await host.terminal.keyboard.press('Control+O');
      await host.terminal.screen.waitUntil(snapshot => snapshot.text.includes('export const probe099 = 99;') === (i % 2 === 0), {timeoutMs: 15000});
      disclosureMs.push(performance.now() - now);
    }
    const resizeMs: number[] = [];
    for (const cols of [60, 120, 80, 100, 60, 120]) {
      const now = performance.now();
      await host.terminal.resize({cols, rows: 36});
      await host.terminal.screen.waitUntil(snapshot => snapshot.frame.cols === cols && snapshot.text.includes(`RTK_TURN_${turns + 1}_DONE`), {timeoutMs: 15000});
      resizeMs.push(performance.now() - now);
    }
    await host.terminal.keyboard.press('Control+O');
    await host.terminal.screen.waitForText('export const probe099 = 99;', {timeoutMs: 15000});
    const layouts = new Map<number, string>();
    const bodyRows = (text: string) => text.split('\n').filter(row => /probe[0-9]|WIDTH_|界|END_/u.test(row)).join('\n');
    for (const cols of [60, 80, 100, 120]) {
      await host.terminal.resize({cols, rows: 36});
      await host.terminal.screen.waitUntil(snapshot => {
        if (snapshot.frame.cols !== cols) return false;
        const rows = snapshot.text.split('\n');
        const start = rows.findIndex(row => row.includes('export const probe099'));
        const end = rows.findIndex((row, index) => index >= start && row.includes('END_99'));
        if (start < 0 || end < start) return false;
        const excerpt = rows.slice(start, end + 1);
        return excerpt.join('').match(/界/gu)?.length === 40 &&
          Math.max(...excerpt.map(row => Bun.stringWidth(row))) >= cols - 4;
      }, {timeoutMs: 15000});
      await resources(`calibration-${cols}`);
      const observed = await host.terminal.screen.capture();
      console.log(JSON.stringify({phase:'calibration', cols, frameCols: observed.frame.cols, body: bodyRows(observed.text), host: JSON.parse(await readFile(join(host.directory, 'resources.json'), 'utf8'))}));
      if (!bodyRows(observed.text).includes('END_99')) throw new Error('Missing calibrated final line');
      layouts.set(cols, bodyRows(observed.text));
    }
    if (new Set(layouts.values()).size !== layouts.size) throw new Error('Calibration did not distinguish all widths');
    const expandedResizeMs: number[] = [];
    for (const cols of [60, 120, 80, 100]) {
      const now = performance.now();
      await host.terminal.resize({cols, rows: 36});
      await host.terminal.screen.waitUntil(snapshot => snapshot.frame.cols === cols && bodyRows(snapshot.text) === layouts.get(cols), {timeoutMs: 15000});
      expandedResizeMs.push(performance.now() - now);
    }
    const range = (text: string) => {
      const lines = Array.from(text.matchAll(/probe([0-9]{3})/gu), match => Number(match[1]));
      if (!lines.length) throw new Error('No visible probe lines');
      return {first: Math.min(...lines), last: Math.max(...lines)};
    };
    const bottom = range(await host.terminal.screen.text());
    const scrollMs: number[] = [];
    const scrollRanges = [];
    for (const key of ['PageUp', 'PageDown', 'PageUp', 'PageDown'] as const) {
      const now = performance.now();
      await host.terminal.keyboard.press(key);
      const observed = await host.terminal.screen.waitUntil(snapshot => {
        const current = range(snapshot.text);
        return key === 'PageUp' ? current.first < bottom.first : current.first === bottom.first && current.last === bottom.last;
      }, {timeoutMs: 15000});
      scrollMs.push(performance.now() - now);
      scrollRanges.push({key, ...range(observed.text)});
    }
    await host.terminal.keyboard.press('Control+O');
    const interacted = await resources('interacted');
    const files = (await readdir(join(host.directory, 'sessions'), {recursive: true})).filter(name => name.endsWith('.jsonl'));
    const sessionBytes = (await Promise.all(files.map(name => stat(join(host.directory, 'sessions', name))))).reduce((total, file) => total + file.size, 0);
    const original = files[0];
    if (!original) throw new Error('Missing saved session');
    const savedPath = join(host.directory, 'sessions', original);
    const saved = await readFile(savedPath, 'utf8');
    const resumeMs: number[] = [];
    const reloadMs: number[] = [];
    for (let i = 0; i < 3; i++) {
      await host.command('/host-session new');
      await host.terminal.screen.waitUntil(snapshot => snapshot.text.includes('HOST_SESSION_NEW') && !snapshot.text.includes('RTK_TURN_'), {timeoutMs: 10000});
      let now = performance.now();
      await host.command(`/host-session ${savedPath}`);
      await host.terminal.screen.waitForText(`RTK_TURN_${turns + 1}_DONE`, {timeoutMs: 15000});
      resumeMs.push(performance.now() - now);
      now = performance.now();
      await host.reload();
      await host.terminal.screen.waitForText(`RTK_TURN_${turns + 1}_DONE`, {timeoutMs: 15000});
      reloadMs.push(performance.now() - now);
      if (await readFile(savedPath, 'utf8') !== saved) throw new Error('Restoration changed session bytes');
    }
    const restored = await resources('restored');
    const cleanup = [];
    for (let i = 0; i < 5; i++) {
      await host.command('/host-session new');
      await host.terminal.screen.waitUntil(snapshot => snapshot.text.includes('HOST_SESSION_NEW') && !snapshot.text.includes('RTK_TURN_'), {timeoutMs: 10000});
      await host.sequence(Array.from({length: readCount}, () => ({name: 'read', parameters: '{"path":"source.ts"}'})));
      cleanup.push(await resources(`fresh-${i}`));
    }
    const result = {sample, enabled, startupMs, turns, toolCalls: turns * readCount + 1, sourceLines: 300, sessionBytes, loadMs, typingMs, disclosureMs, resizeMs, expandedResizeMs, scrollMs, scrollRanges, calibratedLayouts: Array.from(layouts), resumeMs, reloadMs, initial, loaded, interacted, restored, cleanup};
    const line = JSON.stringify(result) + '\n';
    await writeFile(output, line, {flag: 'a'});
    console.log(line.trim());
  } catch (error) {
    console.error((await host.terminal.screen.capture({allowIncomplete: true, deadlineMs: 200})).text);
    throw error;
  } finally {
    await host.close();
  }
}

